import icontract
from typing import List


@icontract.ensure(lambda str1, result: len(result) <= len(str1) and result == str1[:len(result)])
@icontract.ensure(lambda str2, result: len(result) <= len(str2) and result == str2[:len(result)])
@icontract.ensure(lambda str1, str2, result: len(result) == len(str1) or len(result) == len(str2)
                  or str1[len(result)] != str2[len(result)])
def LongestCommonPrefix(str1: List[str], str2: List[str]) -> List[str]:
    i = 0
    while i < len(str1) and i < len(str2) and str1[i] == str2[i]:
        i += 1
    return str1[:i]
